#!/usr/bin/env bash
# Aggregation E2E: the param-driven windowed engine. Events (customer,
# created_at, amount): (alice,10,100) (alice,20,200) (bob,30,50) (alice,150,999)
# (bob,260,5) under a [0,100) tumbling window emit
#   alice [0,100)  count=2 sum=300
#   bob   [0,100)  count=1 sum=50
#   alice [100,200) count=1 sum=999
# as frames {1:key, 2:count, 3:sum, 4:window_start, 5:window_end}.
. "$(dirname "$0")/../lib.sh"
modules_ready || { no aggregation "fluxor modules build failed"; finish; exit; }

build_graph examples/aggregation/linux.yaml || { no aggregation build; finish; exit; }




got=$(run_hex $IN 6)
[ "$got" = "$WANT" ] && ok "aggregation windows 5 events into 3 pane emissions" \
  || no aggregation "got=$got"

finish
